use vstd::prelude::*;

verus! {
    /// Multiply the polynomial with coefficients `c` by x,
    /// i.e. shift all coefficients up by one and make the
    /// constant term 0.0.
    fn legmulx(c: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // length increases by exactly 1
            result.len() == c.len() + 1,
            // constant term is zero
            result[0] == 0.0,
            // every original coefficient c[i] moves to result[i+1]
            forall |i: nat|
                i < c.len() as nat ==>
                result[(i + 1) as usize] == c[i as usize],
    {
        // The result has one more coefficient: x·p(x) shifts all coefficients up by one
        let mut result = Vec::with_capacity(c.len() + 1);
        
        // The constant term of x·p(x) is 0
        result.push(0.0);
        
        // All other coefficients are shifted by one position
        result.extend(c);
        
        result
    }
}

